mapper.select:
select t.other_id as otherId, max(t.id) as lastId, sum(t.unread) as unreadCount
from (
    select case when sender_id = #{me} then receiver_id else sender_id end as other_id,
           id,
           if(receiver_id = #{me} and is_read = 0, 1, 0) as unread
    from message
    where sender_id = #{me} or receiver_id = #{me}
) t
group by t.other_id
order by lastId desc
